    float p3d7_x = param[25];
    float p3d7_y = param[26];
    float p3d7_z = param[27];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[18];
    tmp[2] = -X[0];
    tmp[3] = p3d0_x + tmp[2];
    tmp[4] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[5] = X[7]*tmp[4];
    tmp[6] = -X[1];
    tmp[7] = p3d0_y + tmp[6];
    tmp[8] = X[8]*tmp[4];
    tmp[9] = -X[2];
    tmp[10] = p3d0_z + tmp[9];
    tmp[11] = X[9]*tmp[4];
    tmp[12] = tmp[10]*tmp[11] + tmp[3]*tmp[5] + tmp[7]*tmp[8];
    tmp[13] = X[6]*tmp[4];
    tmp[14] = tmp[4]*tmp[7];
    tmp[15] = -X[7]*tmp[14] + tmp[10]*tmp[13] + tmp[3]*tmp[8];
    tmp[16] = tmp[13]*tmp[3];
    tmp[17] = X[9]*tmp[14];
    tmp[18] = tmp[10]*tmp[8];
    tmp[19] = tmp[16] + tmp[17] - tmp[18];
