    tmp[98] = tmp[11]*tmp[91] + tmp[13]*tmp[92] + tmp[1] - tmp[5]*tmp[97] + tmp[8]*tmp[96];
    tmp[99] = tmp[11]*tmp[97] + tmp[13]*tmp[96] + tmp[22] + tmp[5]*tmp[91] - tmp[8]*tmp[92];
    tmp[100] = tmp[11]*(-tmp[93] - tmp[94] + tmp[95]) + tmp[13]*tmp[97] + tmp[27] + tmp[5]*tmp[92] + tmp[8]*tmp[91];
    tmp[101] = 1.0/(-tmp[0]*tmp[98] + tmp[100]*tmp[30] + tmp[26]*tmp[99]);
    tmp[102] = tmp[25]*tmp[98];
    tmp[103] = p3d5_x + tmp[2];
    tmp[104] = p3d5_y + tmp[6];
    tmp[105] = p3d5_z + tmp[9];
    tmp[106] = tmp[103]*tmp[5] + tmp[104]*tmp[8] + tmp[105]*tmp[11];
    tmp[107] = tmp[103]*tmp[8] - tmp[104]*tmp[5] + tmp[105]*tmp[13];
    tmp[108] = tmp[103]*tmp[13];
    tmp[109] = tmp[104]*tmp[11];
    tmp[110] = tmp[105]*tmp[8];
    tmp[111] = tmp[108] + tmp[109] - tmp[110];
    tmp[112] = -tmp[103]*tmp[11] + tmp[104]*tmp[13] + tmp[105]*tmp[5];
    tmp[113] = tmp[106]*tmp[11] + tmp[107]*tmp[13] + tmp[111]*tmp[8] - tmp[112]*tmp[5] + tmp[1];
    tmp[114] = tmp[106]*tmp[5] - tmp[107]*tmp[8] + tmp[111]*tmp[13] + tmp[112]*tmp[11] + tmp[22];
    tmp[115] = tmp[106]*tmp[8] + tmp[107]*tmp[5] + tmp[112]*tmp[13] + tmp[11]*(-tmp[108] - tmp[109] + tmp[110]) + tmp[27];
    tmp[116] = 1.0/(-tmp[0]*tmp[113] + tmp[114]*tmp[26] + tmp[115]*tmp[30]);
