    h[4] = cx + fx*tmp[71]*(tmp[32]*tmp[72] + tmp[37]*tmp[70] + tmp[40]*tmp[69]);
    h[5] = cy + fy*tmp[71]*(tmp[34]*tmp[72] + tmp[41]*tmp[69] + tmp[42]*tmp[70]);
    h[6] = cx + fx*tmp[86]*(tmp[32]*tmp[87] + tmp[37]*tmp[85] + tmp[40]*tmp[84]);
    h[7] = cy + fy*tmp[86]*(tmp[34]*tmp[87] + tmp[41]*tmp[84] + tmp[42]*tmp[85]);
