    tmp[160] = tmp[11]*(-tmp[153] - tmp[154] + tmp[155]) + tmp[13]*tmp[157] + tmp[151]*tmp[8] + tmp[152]*tmp[5] + tmp[27];
    tmp[161] = 1.0/(-tmp[0]*tmp[158] + tmp[159]*tmp[26] + tmp[160]*tmp[30]);
    tmp[162] = tmp[158]*tmp[25];
    tmp[163] = p3d9_x + tmp[2];
    tmp[164] = p3d9_y + tmp[6];
    tmp[165] = p3d9_z + tmp[9];
    tmp[166] = tmp[11]*tmp[165] + tmp[163]*tmp[5] + tmp[164]*tmp[8];
    tmp[167] = tmp[13]*tmp[165] + tmp[163]*tmp[8] - tmp[164]*tmp[5];
    tmp[168] = tmp[13]*tmp[163];
    tmp[169] = tmp[11]*tmp[164];
    tmp[170] = tmp[165]*tmp[8];
