    tmp[172] = -tmp[11]*tmp[163] + tmp[13]*tmp[164] + tmp[165]*tmp[5];
    tmp[173] = tmp[11]*tmp[166] + tmp[13]*tmp[167] + tmp[171]*tmp[8] - tmp[172]*tmp[5] + tmp[1];
    tmp[174] = tmp[11]*tmp[172] + tmp[13]*tmp[171] + tmp[166]*tmp[5] - tmp[167]*tmp[8] + tmp[22];
    tmp[175] = tmp[11]*(-tmp[168] - tmp[169] + tmp[170]) + tmp[13]*tmp[172] + tmp[166]*tmp[8] + tmp[167]*tmp[5] + tmp[27];
    tmp[176] = 1.0/(-tmp[0]*tmp[173] + tmp[174]*tmp[26] + tmp[175]*tmp[30]);
    tmp[177] = tmp[173]*tmp[25];
    tmp[178] = p3d10_x + tmp[2];
    tmp[179] = p3d10_y + tmp[6];
    tmp[180] = p3d10_z + tmp[9];
    tmp[181] = tmp[11]*tmp[180] + tmp[178]*tmp[5] + tmp[179]*tmp[8];
    tmp[182] = tmp[13]*tmp[180] + tmp[178]*tmp[8] - tmp[179]*tmp[5];
    tmp[183] = tmp[13]*tmp[178];
    tmp[184] = tmp[11]*tmp[179];
    tmp[185] = tmp[180]*tmp[8];
    tmp[186] = tmp[183] + tmp[184] - tmp[185];
    tmp[187] = -tmp[11]*tmp[178] + tmp[13]*tmp[179] + tmp[180]*tmp[5];
    tmp[188] = tmp[11]*tmp[181] + tmp[13]*tmp[182] + tmp[186]*tmp[8] - tmp[187]*tmp[5] + tmp[1];
    tmp[189] = tmp[11]*tmp[187] + tmp[13]*tmp[186] + tmp[181]*tmp[5] - tmp[182]*tmp[8] + tmp[22];
    tmp[190] = tmp[11]*(-tmp[183] - tmp[184] + tmp[185]) + tmp[13]*tmp[187] + tmp[181]*tmp[8] + tmp[182]*tmp[5] + tmp[27];
    tmp[191] = 1.0/(-tmp[0]*tmp[188] + tmp[189]*tmp[26] + tmp[190]*tmp[30]);
    tmp[192] = tmp[188]*tmp[25];
    tmp[193] = p3d11_x + tmp[2];
    tmp[194] = p3d11_y + tmp[6];
    tmp[195] = p3d11_z + tmp[9];
    tmp[196] = tmp[11]*tmp[195] + tmp[193]*tmp[5] + tmp[194]*tmp[8];
    tmp[197] = tmp[13]*tmp[195] + tmp[193]*tmp[8] - tmp[194]*tmp[5];
    tmp[198] = tmp[13]*tmp[193];
    tmp[199] = tmp[11]*tmp[194];
    tmp[200] = tmp[195]*tmp[8];
    tmp[201] = tmp[198] + tmp[199] - tmp[200];
    tmp[202] = -tmp[11]*tmp[193] + tmp[13]*tmp[194] + tmp[195]*tmp[5];
    tmp[203] = tmp[11]*tmp[196] + tmp[13]*tmp[197] + tmp[1] + tmp[201]*tmp[8] - tmp[202]*tmp[5];
    tmp[204] = tmp[11]*tmp[202] + tmp[13]*tmp[201] + tmp[196]*tmp[5] - tmp[197]*tmp[8] + tmp[22];
    tmp[205] = tmp[11]*(-tmp[198] - tmp[199] + tmp[200]) + tmp[13]*tmp[202] + tmp[196]*tmp[8] + tmp[197]*tmp[5] + tmp[27];
    tmp[206] = 1.0/(-tmp[0]*tmp[203] + tmp[204]*tmp[26] + tmp[205]*tmp[30]);
    tmp[207] = tmp[203]*tmp[25];
